package com.iminiapp.backend.dining;
import com.iminiapp.backend.dining.api.DiningModels.*;import com.iminiapp.backend.dining.application.*;import com.iminiapp.backend.identity.web.AuthenticatedPrincipal;import com.iminiapp.backend.payment.application.MockPaymentService;import com.iminiapp.backend.refund.application.RefundApplicationService;import com.iminiapp.backend.shared.error.BusinessException;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.NONE,properties={"spring.datasource.url=jdbc:mysql://localhost:3306/iminiapp_test?createDatabaseIfNotExist=true&useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai","spring.task.scheduling.enabled=false"}) @Transactional
class DiningReservationIT{
 static final AuthenticatedPrincipal USER=new AuthenticatedPrincipal("dining-it-user","餐饮测试用户","USER",List.of("ROLE_USER")),ADMIN=new AuthenticatedPrincipal("dining-it-admin","餐饮管理员","ADMIN",List.of("ROLE_ADMIN"));
 @Autowired DiningManagementService management;@Autowired DiningReservationService reservation;@Autowired MockPaymentService payment;@Autowired RefundApplicationService refund;@Autowired JdbcTemplate jdbc;
 @Test void 四阶段餐饮预订支付后厨核销报表退款完整链路(){LocalDate day=LocalDate.now().plusDays(1);StoreResponse store=management.saveStore(ADMIN,null,new StoreRequest("IT_DINING_STORE","测试餐厅","测试地址","13800000000",LocalTime.of(8,0),LocalTime.of(22,0),"ACTIVE"));TableResponse table=management.saveTable(null,new TableRequest(store.id(),"A01","临窗餐位","TABLE",4,"ACTIVE"));CategoryResponse category=management.saveCategory(null,new CategoryRequest(store.id(),"HOT","热菜",1,"ACTIVE"));DishResponse dish=management.saveDish(null,new DishRequest(store.id(),category.id(),"FISH","特色鱼",10000L,8000L,null,"招牌菜",true,true,"ACTIVE",20,5));PackageResponse pack=management.savePackage(null,new PackageRequest(store.id(),"SET_A","双人套餐",15000L,null,"双人推荐",true,"ACTIVE",List.of(new PackageItemRequest(dish.id(),1))));
  CreateReservationRequest request=new CreateReservationRequest(store.id(),table.id(),"DINE_IN",day,LocalTime.of(12,0),120,2,"张三","13800000000",null,"少辣",List.of(new OrderItemRequest("DISH",dish.id(),1),new OrderItemRequest("PACKAGE",pack.id(),1)));ReservationResponse created=reservation.create(USER,"dining-it-order",request);assertEquals(28000,created.totalAmountCent());assertEquals(2,jdbc.queryForObject("SELECT locked_quantity FROM bf_dining_stock WHERE dish_id=?",Integer.class,dish.id()));assertThrows(BusinessException.class,()->reservation.create(USER,"dining-it-overlap",request));
  payment.pay(USER,created.orderId(),"dining-it-pay");ReservationResponse paid=reservation.mine(USER).stream().filter(v->v.id()==created.id()).findFirst().orElseThrow();assertEquals("PAID",paid.status());assertEquals(18,jdbc.queryForObject("SELECT on_hand_quantity FROM bf_dining_stock WHERE dish_id=?",Integer.class,dish.id()));assertEquals(2,reservation.tickets(null,null).stream().filter(v->v.reservationId()==created.id()).count());KitchenTicketResponse kitchen=reservation.tickets("KITCHEN","NEW").stream().filter(v->v.reservationId()==created.id()).findFirst().orElseThrow();reservation.kitchen(kitchen.id(),ADMIN,new KitchenActionRequest("ACCEPTED",null));reservation.kitchen(kitchen.id(),ADMIN,new KitchenActionRequest("READY",null));ReservationResponse verified=reservation.verify(ADMIN,new VerifyRequest(paid.verificationCode(),"DINING-DESK-01"));assertEquals("VERIFIED",verified.status());assertEquals("COMPLETED",reservation.complete(ADMIN,created.id()).status());assertEquals(1,reservation.overview(day,day).orderCount());assertFalse(reservation.sales(day,day).isEmpty());assertTrue(new String(reservation.csv(day,day,store.id(),null),java.nio.charset.StandardCharsets.UTF_8).contains(created.reservationNo()));
  int availableBefore=jdbc.queryForObject("SELECT available_quantity FROM bf_dining_stock WHERE dish_id=?",Integer.class,dish.id());ReservationResponse cancelled=reservation.create(USER,"dining-it-cancel",new CreateReservationRequest(store.id(),table.id(),"DINE_IN",day,LocalTime.of(17,0),30,1,"张三","13800000000",null,null,List.of(new OrderItemRequest("DISH",dish.id(),1))));assertEquals("CANCELLED",reservation.cancel(USER,cancelled.id()).status());assertEquals(availableBefore,jdbc.queryForObject("SELECT available_quantity FROM bf_dining_stock WHERE dish_id=?",Integer.class,dish.id()));
  ReservationResponse refundable=reservation.create(USER,"dining-it-refund",new CreateReservationRequest(store.id(),table.id(),"DINE_IN",day,LocalTime.of(18,0),30,1,"张三","13800000000",null,null,List.of(new OrderItemRequest("DISH",dish.id(),1))));payment.pay(USER,refundable.orderId(),"dining-refund-pay");refund.apply(USER,refundable.orderId(),"dining-refund-apply","行程变化");assertEquals("REFUND_PENDING",jdbc.queryForObject("SELECT status FROM bf_dining_reservation WHERE id=?",String.class,refundable.id()));
 }
}
